// src/api/LogsApi.js
import { get } from './HttpClient';

function buildQuery(params = {}) {
  const qs = new URLSearchParams();

  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (!s) return;
    qs.set(k, s);
  });

  const q = qs.toString();
  return q ? `?${q}` : '';
}

/**
 * 명세 우선: GET /logs?page&size&from&to&keyword&aiLabel&eventType&sort
 * (백엔드가 아직 없으면 404 날 수 있고, 그때 UseLogs 훅이 /logs/recent로 fallback 함)
 */
export function fetchLogs(params = {}) {
  return get(`/logs${buildQuery(params)}`);
}

/** 백엔드: GET /logs/recent?limit=50 */
export function fetchRecentLogs(limit = 50) {
  return get(`/logs/recent?limit=${limit}`);
}
